from lib import *
S = SS('m21')
steps = [
    step("数组字段上的索引按元素生成条目(multikey)。对每种取值单独建一个一文档的集合,用 validate 看索引条目数:['x','y','z'] 是 3 条,['x'] 1 条,空数组 [] 1 条,字段缺失 1 条,标量 'x' 1 条,['x','x','x'] 重复元素只有 1 条,[['x','y'],'z'] 2 条,[null,'x'] 2 条;8 个文档放进同一个集合,条目数 12,等于逐个相加。explain 里 isMultiKey: true,multiKeyPaths: { t: ['t'] }。", t=tl(S(1)), mark=lidx(S(1), 'isMultiKey: true', '条目数 = 12'), done=lidx(S(1), "['x','y','z']", "['x','x','x']", '字段缺失'), kv=KV([['每个元素一条', '[x,y,z] → 3'], ['空数组 / 缺失 / 标量', '各 1 条'], ['重复元素', '同一文档内去重'], ['isMultiKey', 'true']], ['每个元素一条'])),
    step("条目数随数组长度线性增长:10,000 个文档,每个数组 1 / 5 / 20 / 100 个元素时,索引条目 10,000 / 50,000 / 200,000 / 1,000,000,索引大小 114,688 / 499,712 / 1,908,736 / 8,835,072 字节,平均每个文档 11 / 50 / 191 / 884 字节。", t=tl(S(2)), mark=lidx(S(2), '1,000,000', '884 B'), done=lidx(S(2), '10,000', '50,000', '200,000'), b=bars([['1 个元素', 114688, '114,688 B'], ['5 个元素', 499712, '499,712 B'], ['20 个元素', 1908736, '1,908,736 B'], ['100 个元素', 8835072, '8,835,072 B']], 8835072, mark=[3], done=[0, 1, 2]), kv=KV([['条目数', '= 文档数 × 平均去重后的元素数'], ['索引大小', '100 个元素时约是 1 个元素的 77 倍']], ['条目数'])),
    step("同一个文档里数组的重复值只会生成一条索引条目:文档 {t: ['a','a','a','b']}(4 个元素、2 个不同值),索引条目数是 2。", t=tl(S(3)), mark=lidx(S(3), '条目数 = 2'), done=lidx(S(3), '[a,a,a,b]'), kv=KV([['重复值', '同一个文档内只存一条'], ['[a,a,a,b]', '2 条']], ['重复值'])),
    step("查询怎么用 multikey 索引:5 万个文档,tags 是 3 个元素的数组。find({tags: \"a3\"}) 检查 5000 个键、读 5000 个文档,返回 5000;find({tags: {$all: [\"a3\", \"b2\"]}}) 也只用 tags 的一个条件定界,检查 5000 个键,返回 714;整个数组相等 find({tags: [\"a3\", \"b2\", \"c0\"]}) 检查 5001 个键、5000 个文档,返回 238。", t=tl(S(4)), mark=lidx(S(4), 'nReturned: 714', 'nReturned: 238'), done=lidx(S(4), 'nReturned: 5000'), kv=KV([['$all', '用其中一个元素定界,其余在 FETCH 后过滤'], ['整个数组相等', '同样要读 5000 个文档过滤']], ['$all'])),
    step("$elemMatch 与普通条件不同:{\"items.k\": \"a3\", \"items.v\": 1} 可以由数组里不同的元素各满足一个条件,匹配 2143 个文档,计划检查 5000 个键、5000 个文档;{items: {$elemMatch: {k: \"a3\", v: 1}}} 要求同一个元素同时满足,匹配 1000 个文档,只检查 1000 个键、1000 个文档。", t=tl(S(5)), mark=lidx(S(5), '2143', '1000'), done=lidx(S(5), 'IXSCAN(items.k_1_items.v_1)'), b=bars([['普通条件(可由不同元素满足)', 2143, '2143 个 / 检查 5000'], ['$elemMatch(同一个元素)', 1000, '1000 个 / 检查 1000']], 2143, mark=[1], done=[0]), kv=KV([['普通条件', '各条件可由不同元素满足'], ['$elemMatch', '同一个元素同时满足,索引界限更紧']], ['$elemMatch'])),
    step("multikey 的写入代价:带 t 上索引时批量插入 10,000 个文档,每个文档 1 个元素 24 ms,每个文档 100 个元素 821 ms——每个元素都要在索引里插一条。", t=tl(S(6)), mark=lidx(S(6), '100 个元素'), done=lidx(S(6), '1 个元素'), b=bars([['1 个元素 / 文档', 24, '24 ms'], ['100 个元素 / 文档', 821, '821 ms']], 821, mark=[1], done=[0]), kv=KV([['写入', '每个元素一次索引插入'], ['100 个元素', '约是 1 个元素的 34 倍']], ['写入'])),
]
A = mkartm('m21', 21, 'MongoDB,多键索引,multikey,数组,索引条目,真实验证,动画演示',
    '实测多键索引:数组每个元素一条索引条目(空数组、缺失、标量各 1 条,同一文档内重复元素去重),条目数和索引大小随数组长度线性增长(100 个元素时每个文档 884 字节),$elemMatch 比普通条件界限更紧,写入代价随元素数线性增长。',
    '数组字段上的索引会生成多少条索引条目?它占多大?$elemMatch 为什么更快?这篇用 validate 数条目、用 explain 看检查的键数,并量一下写入代价。',
    [('3 条', '数组 [x,y,z] 在多键索引里生成的条目数;空数组、缺失、标量各 1 条'), ('884 B', '每个数组 100 个元素时,平均每个文档在索引里占的字节数(1 个元素只有 11 B)'), ('821 ms', '10,000 个文档、每个 100 个元素的批量插入耗时(1 个元素是 24 ms)')],
    [('一元素一条', '<p>数组字段的索引按元素生成条目,同一个文档里重复的元素只算一条;空数组、字段缺失、标量各一条。explain 里 <code>isMultiKey</code> 为 true。</p>'),
     ('线性增长', '<p>索引条目数和大小随数组长度线性增长:每个数组 100 个元素的 10,000 个文档,索引 8.8 MB,是 1 个元素时的 77 倍。</p>'),
     ('重复值', '<p>数组里重复的值在索引里只存一条,<code>[a,a,a,b]</code> 只有 2 条。</p>'),
     ('查询', '<p><code>$all</code> 与整个数组相等的查询只用其中一个元素定界,其余条件在 FETCH 后过滤,所以检查的键数和文档数与单值查询一样多。</p>'),
     ('$elemMatch', '<p>普通条件可以由数组里不同的元素各满足一个;<code>$elemMatch</code> 要求同一个元素满足,索引界限更紧,检查的键和文档数只有前者的 1/5。</p>'),
     ('写入代价', '<p>每个元素都要在索引里插一条,批量插入每个文档 100 个元素比 1 个元素慢了约 34 倍。</p>')],
    steps,
    [ENV_M + '。条目数来自 validate({full: true}).keysPerIndex;大小来自 collStats 的 indexSizes(fsync 之后读)',
     '没有验证:复合 multikey 索引的 multiKeyPaths 细节与排序;数组套数组的条目数在更深层的表现;multikey 索引上 $size、$in 的界限;multikey 对唯一索引的影响(同一文档内重复不冲突,是否因此需要特别处理);部分索引与 multikey 的组合;写入耗时是否受 journal 影响'],
    '多键索引的索引条目')
